const LAW_BANK = [{"id":1,"concept":"Dental Records","stem":"Who legally owns the physical dental record in a private dental office?","choices":["The patient","The dental office or practitioner","The insurance company","The provincial regulator"],"answer":1,"why":"The provider or practice owns the physical record, while the patient has rights of access and copies.","zh":"医疗机构或执业者拥有实体病历，但患者有权查阅并取得副本。","rationales":[{"en":"Patients have access rights, but they do not usually own the original physical chart.","zh":"患者有查阅权，但通常不拥有原始实体病历。"},{"en":"Correct: the practice owns the original record and must safeguard it.","zh":"正确：诊所拥有原始病历并有义务妥善保管。"},{"en":"Insurers may receive authorized information but do not own the chart.","zh":"保险公司可在授权下取得信息，但不拥有病历。"},{"en":"The regulator sets standards but does not own individual charts.","zh":"监管机构制定标准，但不拥有个别病历。"}],"level":"Board-style","pearl":"The provider or practice owns the physical record, while the patient has rights of access and copies."},{"id":2,"concept":"Dental Records","stem":"A patient requests a copy of the complete dental record. What is the best response?","choices":["Refuse because the office owns the chart","Provide access or copies within legal requirements and keep the original","Give the original and keep no copy","Release only radiographs"],"answer":1,"why":"Ownership of the record does not cancel the patient’s right to access their information.","zh":"病历所有权不影响患者查阅其个人信息的权利。","rationales":[{"en":"Ownership does not justify an absolute refusal.","zh":"拥有病历并不构成绝对拒绝的理由。"},{"en":"Correct: provide access or copies while retaining the original record.","zh":"正确：提供查阅或副本，同时保留原始病历。"},{"en":"The original should remain with the office unless law requires otherwise.","zh":"除非法律另有要求，原始病历应由诊所保留。"},{"en":"The request can include the full record, not radiographs alone.","zh":"患者可要求完整病历，而不仅是X光片。"}],"level":"Board-style","pearl":"Ownership of the record does not cancel the patient’s right to access their information."},{"id":3,"concept":"Dental Records","stem":"How should an error in a paper chart be corrected?","choices":["Erase it completely","Use correction fluid","Draw a single line through it, enter the correction, date, and initial","Delete the page"],"answer":2,"why":"Corrections must preserve the original entry and create a transparent audit trail.","zh":"更正必须保留原始记录，并形成透明的审计轨迹。","rationales":[{"en":"Erasing destroys the original information and undermines record integrity.","zh":"擦除会破坏原始信息并损害病历完整性。"},{"en":"Correction fluid hides the original entry and is inappropriate.","zh":"涂改液会遮盖原始内容，不合适。"},{"en":"Correct: a single-line strikeout plus date and initials preserves transparency.","zh":"正确：单线划除并注明日期和签名可保持透明。"},{"en":"Deleting a page removes relevant clinical history.","zh":"删除整页会丢失重要临床资料。"}],"level":"Clinical","pearl":"Corrections must preserve the original entry and create a transparent audit trail."},{"id":4,"concept":"Dental Records","stem":"Which note is most appropriate after a missed appointment?","choices":["Patient is irresponsible","No-show","Patient did not attend; voicemail left at 2:15 p.m.","Patient probably forgot again"],"answer":2,"why":"Objective, factual, time-stamped documentation is required.","zh":"应采用客观、事实性并标明时间的记录。","rationales":[{"en":"This is judgmental and not clinically objective.","zh":"该表述带有评价性，不够客观。"},{"en":"This is too vague and lacks follow-up details.","zh":"该记录过于笼统，缺少后续处理。"},{"en":"Correct: it states the event and action taken without judgment.","zh":"正确：记录事实和采取的行动，不含主观评价。"},{"en":"Speculation does not belong in a clinical record.","zh":"推测不应写入临床病历。"}],"level":"Board-style","pearl":"Objective, factual, time-stamped documentation is required."},{"id":5,"concept":"Confidentiality","stem":"When may confidential information be disclosed without patient consent?","choices":["Whenever a colleague is curious","When disclosure is required by law or necessary to prevent serious harm","Whenever the patient is late","Whenever family asks"],"answer":1,"why":"Confidentiality has limited legal exceptions, including mandatory reporting and serious safety concerns.","zh":"保密义务存在有限法律例外，包括强制报告和严重安全风险。","rationales":[{"en":"Curiosity is never a valid reason for disclosure.","zh":"好奇绝不是披露信息的合法理由。"},{"en":"Correct: lawful mandatory disclosure or prevention of serious harm may override consent.","zh":"正确：依法强制披露或防止严重伤害时可不经同意。"},{"en":"Lateness has no relevance to confidentiality.","zh":"迟到与保密无关。"},{"en":"Family members are not automatically entitled to information.","zh":"家属并非自动有权取得信息。"}],"level":"Board-style","pearl":"Confidentiality has limited legal exceptions, including mandatory reporting and serious safety concerns."},{"id":6,"concept":"Confidentiality","stem":"The best way to discuss a patient case for education is to:","choices":["Use the patient’s full name","Remove identifiers and share only necessary information","Post the radiograph on social media","Discuss it in a public elevator"],"answer":1,"why":"De-identification and minimum necessary disclosure protect privacy.","zh":"去除身份信息并仅披露必要内容有助于保护隐私。","rationales":[{"en":"Using a full name unnecessarily identifies the patient.","zh":"使用全名会不必要地识别患者身份。"},{"en":"Correct: remove identifiers and limit details to what is needed.","zh":"正确：去除身份信息并限制披露范围。"},{"en":"Social media posting risks unauthorized disclosure.","zh":"在社交媒体发布存在未经授权披露风险。"},{"en":"Public spaces are inappropriate for confidential discussion.","zh":"公共场所不适合讨论机密信息。"}],"level":"Clinical","pearl":"De-identification and minimum necessary disclosure protect privacy."},{"id":7,"concept":"Consent","stem":"Valid informed consent requires:","choices":["Only a signature","Capacity, adequate information, voluntariness, and agreement","Payment in advance","A witness in every case"],"answer":1,"why":"Consent is a process requiring understanding and a voluntary decision, not merely a form.","zh":"同意是一个包含理解和自愿决定的过程，不只是签字。","rationales":[{"en":"A signature alone does not prove understanding or voluntariness.","zh":"单独签字不能证明患者理解且自愿。"},{"en":"Correct: capacity, disclosure, understanding, voluntariness, and agreement are essential.","zh":"正确：能力、信息披露、理解、自愿和同意缺一不可。"},{"en":"Payment is unrelated to informed consent validity.","zh":"付款与知情同意的有效性无关。"},{"en":"A witness is not universally required.","zh":"并非所有情况都必须有见证人。"}],"level":"Board-style","pearl":"Consent is a process requiring understanding and a voluntary decision, not merely a form."},{"id":8,"concept":"Consent","stem":"A patient agrees to treatment after receiving full information but does not sign a form. This may be:","choices":["Implied consent","Express verbal consent","No consent","Emergency exception"],"answer":1,"why":"Express consent may be verbal or written, depending on the procedure and law.","zh":"明确同意可为口头或书面形式，取决于治疗和法律要求。","rationales":[{"en":"Implied consent is inferred from actions, not a clear verbal agreement.","zh":"默示同意来自行为推断，而非明确口头同意。"},{"en":"Correct: a clearly communicated verbal agreement is express consent.","zh":"正确：明确口头表达的同意属于明示同意。"},{"en":"Consent exists even without a written form when verbal consent is legally sufficient.","zh":"在法律允许口头同意时，没有书面表格不等于没有同意。"},{"en":"The patient is conscious and informed, so this is not an emergency exception.","zh":"患者清醒且已获知情，因此不属于紧急例外。"}],"level":"Board-style","pearl":"Express consent may be verbal or written, depending on the procedure and law."},{"id":9,"concept":"Consent","stem":"A competent adult refuses recommended radiographs after risks are explained. The hygienist should:","choices":["Force the radiographs","Respect the refusal, document the discussion, and adjust care appropriately","Dismiss the patient immediately","Hide the refusal from the chart"],"answer":1,"why":"Competent patients may refuse care after informed discussion.","zh":"具备能力的患者在知情后有权拒绝治疗。","rationales":[{"en":"Forced treatment violates autonomy and may constitute battery.","zh":"强制治疗侵犯自主权，并可能构成非法接触。"},{"en":"Correct: respect informed refusal and document it thoroughly.","zh":"正确：尊重知情拒绝并完整记录。"},{"en":"Immediate dismissal is not automatically required.","zh":"并非必须立即终止医患关系。"},{"en":"Refusal and counselling must be documented.","zh":"拒绝及相关沟通必须记录。"}],"level":"Clinical","pearl":"Competent patients may refuse care after informed discussion."},{"id":10,"concept":"Consent","stem":"Who usually provides consent for a young child who lacks legal capacity?","choices":["Any staff member","A parent or legally authorized guardian","Another patient","The child’s teacher"],"answer":1,"why":"A parent or authorized guardian generally provides substitute consent for a minor lacking capacity.","zh":"对缺乏能力的未成年人，通常由父母或法定监护人代为同意。","rationales":[{"en":"Staff cannot substitute for the legal decision-maker.","zh":"工作人员不能代替法定决策者。"},{"en":"Correct: a parent or authorized guardian is the usual substitute decision-maker.","zh":"正确：父母或法定监护人通常为替代决策者。"},{"en":"Another patient has no legal authority.","zh":"其他患者没有法律授权。"},{"en":"Teachers do not automatically have healthcare consent authority.","zh":"教师并非自动具有医疗同意权。"}],"level":"Board-style","pearl":"A parent or authorized guardian generally provides substitute consent for a minor lacking capacity."},{"id":11,"concept":"Consent","stem":"Consent obtained through intimidation is invalid because it lacks:","choices":["Disclosure","Voluntariness","Documentation","Diagnosis"],"answer":1,"why":"Consent must be given freely without coercion.","zh":"同意必须在无胁迫的情况下自由作出。","rationales":[{"en":"Disclosure may have occurred, but coercion still invalidates consent.","zh":"即使已披露信息，胁迫仍会使同意无效。"},{"en":"Correct: voluntariness is absent when intimidation is used.","zh":"正确：存在威胁时缺乏自愿性。"},{"en":"Documentation does not cure coercion.","zh":"记录不能弥补胁迫问题。"},{"en":"A diagnosis does not determine whether consent is voluntary.","zh":"诊断并不决定同意是否自愿。"}],"level":"Board-style","pearl":"Consent must be given freely without coercion."},{"id":12,"concept":"Consent","stem":"An unconscious patient requires immediate care to prevent serious harm and no substitute decision-maker is available. Care may proceed under:","choices":["Implied emergency consent","Marketing consent","Contract law only","No legal basis"],"answer":0,"why":"Emergency law may imply consent when delay would threaten life or health.","zh":"在延误会危及生命或健康时，法律可推定紧急同意。","rationales":[{"en":"Correct: consent may be implied in a genuine emergency when the patient cannot decide.","zh":"正确：在真实紧急情况下，患者无法决定时可推定同意。"},{"en":"Marketing consent is unrelated to emergency treatment.","zh":"营销同意与紧急治疗无关。"},{"en":"Contract law alone does not describe the emergency exception.","zh":"单靠合同法不能解释紧急例外。"},{"en":"There is a recognized legal basis for necessary emergency care.","zh":"必要紧急护理具有公认法律依据。"}],"level":"Clinical","pearl":"Emergency law may imply consent when delay would threaten life or health."},{"id":13,"concept":"Ethical Principles","stem":"Respecting a patient’s informed choice best demonstrates:","choices":["Autonomy","Justice","Fidelity","Nonmaleficence"],"answer":0,"why":"Autonomy protects the patient’s right to make informed decisions.","zh":"自主原则保护患者作出知情决定的权利。","rationales":[{"en":"Correct: autonomy centres on self-determination.","zh":"正确：自主原则强调自我决定。"},{"en":"Justice concerns fairness and equitable treatment.","zh":"公正原则关注公平和平等治疗。"},{"en":"Fidelity concerns keeping commitments.","zh":"忠诚原则关注履行承诺。"},{"en":"Nonmaleficence focuses on avoiding harm.","zh":"不伤害原则强调避免伤害。"}],"level":"Board-style","pearl":"Autonomy protects the patient’s right to make informed decisions."},{"id":14,"concept":"Ethical Principles","stem":"Acting to promote a patient’s oral health is an example of:","choices":["Beneficence","Veracity","Autonomy","Confidentiality"],"answer":0,"why":"Beneficence means acting for the patient’s good.","zh":"行善原则指为患者利益采取行动。","rationales":[{"en":"Correct: promoting health and benefit reflects beneficence.","zh":"正确：促进健康和利益体现行善原则。"},{"en":"Veracity concerns truthfulness.","zh":"诚实原则关注真实。"},{"en":"Autonomy concerns patient choice.","zh":"自主原则关注患者选择。"},{"en":"Confidentiality concerns privacy of information.","zh":"保密原则关注信息隐私。"}],"level":"Board-style","pearl":"Beneficence means acting for the patient’s good."},{"id":15,"concept":"Ethical Principles","stem":"Avoiding a procedure when its likely harm exceeds its benefit reflects:","choices":["Nonmaleficence","Justice","Veracity","Fidelity"],"answer":0,"why":"Nonmaleficence requires avoiding preventable harm.","zh":"不伤害原则要求避免可预防的伤害。","rationales":[{"en":"Correct: refraining from disproportionate harm demonstrates nonmaleficence.","zh":"正确：避免不成比例的伤害体现不伤害原则。"},{"en":"Justice addresses fair distribution and treatment.","zh":"公正原则涉及公平分配和待遇。"},{"en":"Veracity is the duty to tell the truth.","zh":"诚实原则是如实告知的义务。"},{"en":"Fidelity is loyalty and keeping promises.","zh":"忠诚原则指忠于承诺。"}],"level":"Clinical","pearl":"Nonmaleficence requires avoiding preventable harm."},{"id":16,"concept":"Ethical Principles","stem":"Providing the same standard of care regardless of income or background reflects:","choices":["Justice","Autonomy","Veracity","Confidentiality"],"answer":0,"why":"Justice requires fairness and nondiscrimination.","zh":"公正原则要求公平且不歧视。","rationales":[{"en":"Correct: equal access and fair treatment reflect justice.","zh":"正确：平等获得和公平治疗体现公正原则。"},{"en":"Autonomy concerns individual decision-making.","zh":"自主原则涉及个人决策。"},{"en":"Veracity concerns honesty.","zh":"诚实原则涉及真实。"},{"en":"Confidentiality concerns protection of information.","zh":"保密原则涉及信息保护。"}],"level":"Board-style","pearl":"Justice requires fairness and nondiscrimination."},{"id":17,"concept":"Ethical Principles","stem":"Telling a patient that a mistake occurred demonstrates:","choices":["Veracity","Paternalism","Justice","Utility"],"answer":0,"why":"Veracity is the obligation to be truthful.","zh":"诚实原则是如实告知的义务。","rationales":[{"en":"Correct: honest disclosure reflects veracity.","zh":"正确：诚实披露体现诚实原则。"},{"en":"Paternalism substitutes the provider’s judgment for the patient’s choice.","zh":"家长主义以医务人员判断取代患者选择。"},{"en":"Justice concerns fairness.","zh":"公正原则关注公平。"},{"en":"Utility is not the primary principle illustrated.","zh":"此处主要体现的不是功利原则。"}],"level":"Board-style","pearl":"Veracity is the obligation to be truthful."},{"id":18,"concept":"Ethical Principles","stem":"Following through on a promised referral best demonstrates:","choices":["Fidelity","Justice","Autonomy","Nonmaleficence"],"answer":0,"why":"Fidelity means keeping professional commitments and maintaining trust.","zh":"忠诚原则指履行专业承诺并维持信任。","rationales":[{"en":"Correct: keeping a promise reflects fidelity.","zh":"正确：履行承诺体现忠诚。"},{"en":"Justice concerns fairness, not promise-keeping.","zh":"公正原则关注公平，不是履行承诺。"},{"en":"Autonomy concerns patient choices.","zh":"自主原则关注患者选择。"},{"en":"Nonmaleficence concerns avoiding harm.","zh":"不伤害原则关注避免伤害。"}],"level":"Clinical","pearl":"Fidelity means keeping professional commitments and maintaining trust."},{"id":19,"concept":"Professionalism","stem":"A hygienist notices a colleague repeatedly providing unsafe care. The best first action is to:","choices":["Ignore it","Privately address the concern at the lowest effective level, then escalate if needed","Post about it online","Tell patients immediately without investigation"],"answer":1,"why":"Ethical concerns should be addressed promptly, privately, and through appropriate channels.","zh":"伦理问题应及时、私下并通过适当渠道处理。","rationales":[{"en":"Ignoring unsafe practice may place patients at risk.","zh":"忽视不安全行为会使患者处于风险中。"},{"en":"Correct: use the least escalatory effective step while protecting patients.","zh":"正确：在保护患者的前提下，先采用最低有效层级处理。"},{"en":"Public posting breaches professionalism and may violate privacy.","zh":"公开发布会违反专业规范并可能侵犯隐私。"},{"en":"Unverified disclosure to patients may be inappropriate and harmful.","zh":"未经核实就告知患者可能不当且有害。"}],"level":"Board-style","pearl":"Ethical concerns should be addressed promptly, privately, and through appropriate channels."},{"id":20,"concept":"Professionalism","stem":"Practising outside the authorized scope is primarily a breach of:","choices":["Professional accountability","Autonomy","Justice","Confidentiality"],"answer":0,"why":"Professionals are accountable for practising within competence and legal scope.","zh":"专业人员有责任在能力和法定范围内执业。","rationales":[{"en":"Correct: scope limits are a core accountability obligation.","zh":"正确：遵守执业范围是核心责任。"},{"en":"Autonomy does not authorize a clinician to exceed scope.","zh":"自主原则不能授权临床人员超越执业范围。"},{"en":"Justice is not the main issue.","zh":"公正并非主要问题。"},{"en":"Confidentiality concerns information privacy, not scope.","zh":"保密涉及信息隐私，而非执业范围。"}],"level":"Board-style","pearl":"Professionals are accountable for practising within competence and legal scope."},{"id":21,"concept":"Professionalism","stem":"When a clinician delegates a task, the clinician remains responsible for:","choices":["Nothing once delegated","Appropriate delegation, supervision, and patient safety","The assistant’s personal finances","Only scheduling"],"answer":1,"why":"Delegation does not remove professional accountability.","zh":"委派任务并不免除专业责任。","rationales":[{"en":"Responsibility is not eliminated by delegation.","zh":"委派并不会消除责任。"},{"en":"Correct: the delegating clinician remains accountable for safe delegation and supervision.","zh":"正确：委派者仍需对安全委派和监督负责。"},{"en":"Personal finances are unrelated.","zh":"个人财务无关。"},{"en":"Responsibility extends beyond scheduling.","zh":"责任不止于排班。"}],"level":"Clinical","pearl":"Delegation does not remove professional accountability."},{"id":22,"concept":"Civil Law","stem":"Negligence generally requires proof of:","choices":["Duty, breach, causation, and damages","Intent to harm only","A criminal conviction","A signed contract only"],"answer":0,"why":"Professional negligence requires a duty of care, breach of standard, causation, and actual harm.","zh":"专业疏忽通常需证明照护义务、违反标准、因果关系和实际损害。","rationales":[{"en":"Correct: all four elements are generally necessary.","zh":"正确：通常需要这四个要素。"},{"en":"Negligence does not require intent to harm.","zh":"疏忽不要求有伤害意图。"},{"en":"Civil negligence can exist without criminal conviction.","zh":"民事疏忽不需要刑事定罪。"},{"en":"A written contract is not the sole basis of negligence.","zh":"书面合同不是疏忽责任的唯一基础。"}],"level":"Board-style","pearl":"Professional negligence requires a duty of care, breach of standard, causation, and actual harm."},{"id":23,"concept":"Civil Law","stem":"A clinician intentionally performs a procedure after a competent patient clearly refuses. This may constitute:","choices":["Battery","Negligence only","Defamation","No wrongdoing"],"answer":0,"why":"Intentional unauthorized physical contact may constitute battery.","zh":"故意进行未经授权的身体接触可能构成非法接触。","rationales":[{"en":"Correct: treatment after clear refusal can be battery.","zh":"正确：在明确拒绝后仍治疗可构成非法接触。"},{"en":"The intentional nature makes battery more apt than negligence alone.","zh":"由于行为是故意的，比单纯疏忽更符合非法接触。"},{"en":"Defamation involves false statements harming reputation.","zh":"诽谤涉及损害名誉的虚假陈述。"},{"en":"Proceeding without consent is legally and ethically problematic.","zh":"未经同意继续治疗存在法律和伦理问题。"}],"level":"Board-style","pearl":"Intentional unauthorized physical contact may constitute battery."},{"id":24,"concept":"Civil Law","stem":"A false statement that unjustly harms a clinician’s reputation may be:","choices":["Defamation","Battery","Consent","Beneficence"],"answer":0,"why":"Defamation concerns false harmful statements about a person.","zh":"诽谤指损害他人名誉的虚假陈述。","rationales":[{"en":"Correct: false reputation-damaging statements may be defamation.","zh":"正确：损害名誉的虚假陈述可能构成诽谤。"},{"en":"Battery concerns unauthorized physical contact.","zh":"非法接触涉及未经授权的身体接触。"},{"en":"Consent is authorization for care.","zh":"同意是对治疗的授权。"},{"en":"Beneficence is an ethical duty to help.","zh":"行善是帮助患者的伦理义务。"}],"level":"Clinical","pearl":"Defamation concerns false harmful statements about a person."},{"id":25,"concept":"Contract Law","stem":"A valid contract generally requires:","choices":["Offer, acceptance, consideration, and legal capacity","A criminal charge","Only a handshake","No mutual understanding"],"answer":0,"why":"Contracts depend on mutual agreement, capacity, and lawful exchange.","zh":"合同通常依赖双方合意、行为能力和合法对价。","rationales":[{"en":"Correct: these are core contract elements.","zh":"正确：这些是合同的核心要素。"},{"en":"A criminal charge is unrelated to contract formation.","zh":"刑事指控与合同成立无关。"},{"en":"A handshake alone may not establish all required elements.","zh":"单纯握手未必满足所有必要要素。"},{"en":"Mutual understanding is central, not absent.","zh":"双方理解是核心，而非不需要。"}],"level":"Board-style","pearl":"Contracts depend on mutual agreement, capacity, and lawful exchange."},{"id":26,"concept":"Criminal Law","stem":"Falsifying patient records may lead to:","choices":["Only a minor scheduling issue","Professional discipline and potentially criminal consequences","Automatic patient consent","No consequence if done electronically"],"answer":1,"why":"Intentional falsification can breach professional, civil, and criminal obligations.","zh":"故意伪造病历可能违反专业、民事及刑事义务。","rationales":[{"en":"Falsification is far more serious than scheduling.","zh":"伪造病历远比排班问题严重。"},{"en":"Correct: it can trigger discipline and legal liability.","zh":"正确：可引发纪律处分和法律责任。"},{"en":"False records do not create valid consent.","zh":"虚假记录不能产生有效同意。"},{"en":"Electronic falsification is still misconduct.","zh":"电子病历伪造同样属于不当行为。"}],"level":"Board-style","pearl":"Intentional falsification can breach professional, civil, and criminal obligations."},{"id":27,"concept":"Privacy","stem":"The “minimum necessary” privacy principle means:","choices":["Disclose the entire chart every time","Use or disclose only the information needed for the purpose","Never share information even with consent","Let all staff browse records"],"answer":1,"why":"Privacy protection requires limiting access and disclosure to what is necessary.","zh":"隐私保护要求将查阅和披露限制在必要范围内。","rationales":[{"en":"Full-chart disclosure is often excessive.","zh":"每次披露完整病历通常过度。"},{"en":"Correct: limit information to the legitimate purpose.","zh":"正确：仅提供实现正当目的所需的信息。"},{"en":"Consent may authorize appropriate disclosure.","zh":"患者同意可授权适当披露。"},{"en":"Staff access must be role-based and necessary.","zh":"员工查阅应基于职责和必要性。"}],"level":"Clinical","pearl":"Privacy protection requires limiting access and disclosure to what is necessary."},{"id":28,"concept":"Privacy","stem":"A staff member opens a celebrity patient’s chart out of curiosity. This is:","choices":["Acceptable if nothing is printed","An unauthorized privacy breach","Required quality assurance","Implied consent"],"answer":1,"why":"Access without a care-related need is unauthorized even if nothing is shared.","zh":"即使未打印或外传，无治疗需要的查阅也属于未经授权。","rationales":[{"en":"Viewing alone can breach privacy.","zh":"仅查看本身也可能侵犯隐私。"},{"en":"Correct: curiosity is not a legitimate purpose.","zh":"正确：好奇不是合法查阅理由。"},{"en":"Quality assurance requires an authorized role and purpose.","zh":"质量管理需要授权职责和正当目的。"},{"en":"Implied consent does not cover curiosity access.","zh":"默示同意不包括因好奇而查阅。"}],"level":"Board-style","pearl":"Access without a care-related need is unauthorized even if nothing is shared."},{"id":29,"concept":"Privacy","stem":"Before emailing patient information, the clinician should first:","choices":["Send it from any personal account","Confirm authorization, recipient, security, and minimum necessary content","Include the full chart by default","Post it to a shared social feed"],"answer":1,"why":"Electronic communication must be authorized, secure, and limited.","zh":"电子沟通必须获得授权、确保安全并限制内容。","rationales":[{"en":"Personal accounts may not meet privacy safeguards.","zh":"个人邮箱可能不符合隐私保护要求。"},{"en":"Correct: verify authorization, destination, security, and scope.","zh":"正确：确认授权、收件人、安全性和披露范围。"},{"en":"The full chart is rarely the minimum necessary.","zh":"完整病历很少属于最小必要范围。"},{"en":"Social feeds are inappropriate for patient information.","zh":"社交平台不适合传输患者信息。"}],"level":"Board-style","pearl":"Electronic communication must be authorized, secure, and limited."},{"id":30,"concept":"Records Retention","stem":"Why must dental records be retained for a required period?","choices":["For decoration","To support continuity of care, legal obligations, and professional accountability","Only for billing","So they can be altered later"],"answer":1,"why":"Retention protects patient care and provides an enduring legal and clinical record.","zh":"病历保存有助于持续照护，并提供长期法律和临床依据。","rationales":[{"en":"Records serve clinical and legal functions, not decoration.","zh":"病历具有临床和法律功能，不是装饰。"},{"en":"Correct: continuity, law, and accountability are central reasons.","zh":"正确：持续照护、法律义务和专业责任是主要原因。"},{"en":"Billing is only one limited function.","zh":"计费只是有限用途之一。"},{"en":"Records must not be altered improperly.","zh":"病历不得被不当修改。"}],"level":"Clinical","pearl":"Retention protects patient care and provides an enduring legal and clinical record."},{"id":31,"concept":"Records Retention","stem":"If a practice closes, patient records should be:","choices":["Discarded immediately","Securely retained or transferred according to law with patient access preserved","Taken home by any employee","Posted online"],"answer":1,"why":"Closure does not end record-retention and privacy duties.","zh":"诊所关闭并不会终止病历保存和隐私义务。","rationales":[{"en":"Immediate destruction may violate retention requirements.","zh":"立即销毁可能违反保存期限要求。"},{"en":"Correct: records must remain secure and accessible through lawful arrangements.","zh":"正确：应依法安全保存或转移，并保障患者查阅。"},{"en":"Employees may not personally take records.","zh":"员工不得私自带走病历。"},{"en":"Online posting would be a serious privacy breach.","zh":"在线公开会构成严重隐私泄露。"}],"level":"Board-style","pearl":"Closure does not end record-retention and privacy duties."},{"id":32,"concept":"Ethical Decision-Making","stem":"The first step in an ethical decision-making process is usually to:","choices":["Choose a punishment","Clearly identify the ethical problem and relevant facts","Ignore the conflict","Ask social media"],"answer":1,"why":"Sound decisions begin with defining the issue and gathering facts.","zh":"良好伦理决策始于明确问题并收集事实。","rationales":[{"en":"Punishment is not the first analytical step.","zh":"处罚不是首个分析步骤。"},{"en":"Correct: identify the dilemma and facts before evaluating options.","zh":"正确：先明确困境和事实，再评估方案。"},{"en":"Ignoring the conflict does not resolve it.","zh":"忽视冲突并不能解决问题。"},{"en":"Social media is not an appropriate confidential ethics forum.","zh":"社交媒体不适合作为机密伦理咨询场所。"}],"level":"Board-style","pearl":"Sound decisions begin with defining the issue and gathering facts."},{"id":33,"concept":"Ethical Decision-Making","stem":"After identifying an ethical dilemma, the clinician should next consider:","choices":["Only personal convenience","Stakeholders, laws, professional standards, principles, and possible consequences","Which option is fastest","Which option earns most money"],"answer":1,"why":"Ethical analysis requires a broad review of duties, stakeholders, standards, and outcomes.","zh":"伦理分析需要综合考虑义务、相关方、标准和后果。","rationales":[{"en":"Personal convenience alone is insufficient.","zh":"仅考虑个人方便远远不够。"},{"en":"Correct: this provides a structured and defensible analysis.","zh":"正确：这样可形成结构化且可辩护的分析。"},{"en":"Speed alone does not determine ethical quality.","zh":"速度本身不能决定伦理正确性。"},{"en":"Financial gain must not override patient welfare and standards.","zh":"经济利益不能凌驾于患者利益和专业标准之上。"}],"level":"Clinical","pearl":"Ethical analysis requires a broad review of duties, stakeholders, standards, and outcomes."},{"id":34,"concept":"Mandatory Reporting","stem":"When law requires reporting suspected abuse, the clinician should:","choices":["Wait for proof beyond doubt","Report according to law based on reasonable suspicion and document objectively","Ask the alleged abuser for permission","Post allegations publicly"],"answer":1,"why":"Mandatory reporting is usually triggered by reasonable suspicion, not certainty.","zh":"强制报告通常以合理怀疑为触发标准，而非绝对确定。","rationales":[{"en":"Waiting for certainty can delay protection.","zh":"等待完全确定可能延误保护。"},{"en":"Correct: follow reporting law and document facts objectively.","zh":"正确：依法报告并客观记录事实。"},{"en":"Permission from the suspected abuser is not required.","zh":"无需取得疑似施害者许可。"},{"en":"Public allegations breach privacy and due process.","zh":"公开指控会侵犯隐私和正当程序。"}],"level":"Board-style","pearl":"Mandatory reporting is usually triggered by reasonable suspicion, not certainty."},{"id":35,"concept":"Professional Boundaries","stem":"Accepting an expensive gift from a vulnerable patient may be problematic because it can:","choices":["Strengthen clinical objectivity","Create a conflict of interest or exploitative boundary","Replace informed consent","Improve record accuracy"],"answer":1,"why":"Large gifts can blur professional boundaries and influence judgment.","zh":"贵重礼物可能模糊专业界限并影响判断。","rationales":[{"en":"It may reduce rather than strengthen objectivity.","zh":"它可能削弱而非增强客观性。"},{"en":"Correct: it can create a conflict or appearance of exploitation.","zh":"正确：可能造成利益冲突或剥削之嫌。"},{"en":"A gift cannot replace informed consent.","zh":"礼物不能替代知情同意。"},{"en":"It has no direct relation to record accuracy.","zh":"它与病历准确性无直接关系。"}],"level":"Board-style","pearl":"Large gifts can blur professional boundaries and influence judgment."},{"id":36,"concept":"Professional Boundaries","stem":"A clinician dating a current patient is concerning primarily because of:","choices":["Power imbalance and impaired professional judgment","Better continuity of care","Lower infection risk","Improved consent validity"],"answer":0,"why":"The professional relationship creates a power imbalance and boundary risk.","zh":"专业关系存在权力不对等和界限风险。","rationales":[{"en":"Correct: the power imbalance may compromise judgment and voluntariness.","zh":"正确：权力不对等可能影响专业判断和自愿性。"},{"en":"Dating does not improve continuity of care.","zh":"恋爱关系不会改善持续照护。"},{"en":"Infection risk is not the core ethical issue.","zh":"感染风险不是核心伦理问题。"},{"en":"Dual relationships may undermine rather than improve consent.","zh":"双重关系可能削弱而非增强同意有效性。"}],"level":"Clinical","pearl":"The professional relationship creates a power imbalance and boundary risk."},{"id":37,"concept":"Documentation","stem":"Why should chart notes avoid personal criticism?","choices":["It improves humour","Records should remain objective, relevant, and professionally defensible","Criticism is mandatory","It increases reimbursement"],"answer":1,"why":"Clinical records should document facts and care, not judgmental commentary.","zh":"临床病历应记录事实和照护，而非带有评价性的评论。","rationales":[{"en":"Humour is not a purpose of clinical documentation.","zh":"幽默不是临床记录的目的。"},{"en":"Correct: objective documentation supports care and accountability.","zh":"正确：客观记录有助于照护和责任追踪。"},{"en":"Criticism is not mandatory.","zh":"批评并非必需。"},{"en":"Reimbursement is not improved by judgmental notes.","zh":"带评价性的记录不会提高报销。"}],"level":"Board-style","pearl":"Clinical records should document facts and care, not judgmental commentary."},{"id":38,"concept":"Documentation","stem":"A late entry should be:","choices":["Backdated to look original","Clearly identified as a late entry with the current date and reason","Inserted secretly","Written over the old note"],"answer":1,"why":"Late entries must be transparent and traceable.","zh":"补记必须透明且可追溯。","rationales":[{"en":"Backdating is deceptive and improper.","zh":"倒签日期具有欺骗性，不合适。"},{"en":"Correct: label it as late, use the current date, and explain context.","zh":"正确：注明补记、使用当前日期并说明原因。"},{"en":"Secret insertion compromises record integrity.","zh":"秘密插入会损害病历完整性。"},{"en":"Writing over an existing note destroys the audit trail.","zh":"覆盖原记录会破坏审计轨迹。"}],"level":"Board-style","pearl":"Late entries must be transparent and traceable."},{"id":39,"concept":"Risk Management","stem":"The best risk-management strategy is to:","choices":["Rely on memory","Provide competent care, communicate clearly, obtain consent, and document thoroughly","Avoid all difficult patients","Never disclose errors"],"answer":1,"why":"Good care, communication, consent, and documentation reduce preventable harm and disputes.","zh":"优质照护、清晰沟通、知情同意和完整记录可减少可预防伤害和争议。","rationales":[{"en":"Memory alone is unreliable and not defensible.","zh":"仅依靠记忆不可靠，也难以辩护。"},{"en":"Correct: these are foundational risk-management practices.","zh":"正确：这些是风险管理的基础措施。"},{"en":"Avoiding difficult patients is neither ethical nor sufficient.","zh":"回避困难患者既不伦理，也不足以管理风险。"},{"en":"Concealing errors worsens ethical and legal risk.","zh":"隐瞒错误会加重伦理和法律风险。"}],"level":"Clinical","pearl":"Good care, communication, consent, and documentation reduce preventable harm and disputes."},{"id":40,"concept":"Scope & Competence","stem":"A clinician is asked to perform a procedure they are not trained or authorized to do. The best response is to:","choices":["Proceed if the patient agrees","Decline, explain the limitation, and arrange appropriate referral","Guess how to do it","Ask an assistant to do it"],"answer":1,"why":"Consent cannot authorize practice beyond competence or legal scope.","zh":"患者同意不能授权临床人员超越能力或法定范围执业。","rationales":[{"en":"Patient agreement does not expand the clinician’s legal scope.","zh":"患者同意不会扩大临床人员的法定执业范围。"},{"en":"Correct: decline and refer appropriately.","zh":"正确：应拒绝并进行适当转诊。"},{"en":"Guessing creates unacceptable risk.","zh":"凭猜测操作会造成不可接受的风险。"},{"en":"Delegating an unauthorized task does not solve the problem.","zh":"将未经授权的任务委派给助手并不能解决问题。"}],"level":"Board-style","pearl":"Consent cannot authorize practice beyond competence or legal scope."},{"id":41,"concept":"Conflict of Interest","stem":"A clinician recommends a product mainly because they receive a commission. The ethical concern is:","choices":["Conflict of interest","Autonomy only","Confidentiality","No concern"],"answer":0,"why":"Financial incentives may bias professional recommendations.","zh":"经济激励可能使专业建议产生偏差。","rationales":[{"en":"Correct: personal financial gain may conflict with patient welfare.","zh":"正确：个人经济利益可能与患者利益冲突。"},{"en":"Autonomy may be affected, but the central issue is conflict of interest.","zh":"自主权可能受影响，但核心问题是利益冲突。"},{"en":"No private information is involved.","zh":"此处不涉及私人信息。"},{"en":"The arrangement creates a real ethical concern.","zh":"该安排确实存在伦理问题。"}],"level":"Board-style","pearl":"Financial incentives may bias professional recommendations."},{"id":42,"concept":"Conflict of Interest","stem":"The best way to manage a potential conflict of interest is to:","choices":["Hide it","Disclose it, prioritize patient welfare, and avoid or manage the conflict","Let profit decide","Document nothing"],"answer":1,"why":"Transparency and patient-first judgment are essential.","zh":"透明披露并优先考虑患者利益至关重要。","rationales":[{"en":"Hiding the conflict undermines trust.","zh":"隐瞒冲突会损害信任。"},{"en":"Correct: disclose and manage or remove the conflict.","zh":"正确：应披露并管理或消除冲突。"},{"en":"Profit should not override patient welfare.","zh":"利润不能凌驾于患者利益之上。"},{"en":"Relevant conflicts and decisions should be documented.","zh":"相关冲突和处理决定应予记录。"}],"level":"Clinical","pearl":"Transparency and patient-first judgment are essential."},{"id":43,"concept":"Termination of Care","stem":"Before ending a professional relationship, the clinician should generally:","choices":["Abandon the patient immediately","Give reasonable notice, facilitate continuity, and document the process","Destroy the chart","Refuse emergency care during the transition"],"answer":1,"why":"Termination must avoid abandonment and support continuity of care.","zh":"终止医患关系时必须避免遗弃并保障持续照护。","rationales":[{"en":"Immediate abandonment may breach professional duty.","zh":"立即遗弃可能违反专业义务。"},{"en":"Correct: reasonable notice and transition support are required.","zh":"正确：应给予合理通知并协助过渡。"},{"en":"Records must be retained, not destroyed.","zh":"病历必须保留，不能销毁。"},{"en":"Urgent needs still require appropriate management during transition.","zh":"过渡期间的紧急需求仍需妥善处理。"}],"level":"Board-style","pearl":"Termination must avoid abandonment and support continuity of care."},{"id":44,"concept":"Consent & Capacity","stem":"An adult patient with mild cognitive impairment can explain the proposed debridement, its risks, alternatives, and consequences of refusal. Who should provide consent?","choices":["The patient","The nearest relative automatically","The dental hygienist","A substitute decision-maker despite the patient’s understanding"],"answer":0,"why":"Capacity is decision-specific. A patient who understands and appreciates the relevant information may consent independently.","zh":"决定能力具有事项特异性。能够理解并评估相关信息的患者可自行作出同意。","rationales":[{"en":"Correct: the patient demonstrates decision-specific capacity and should make the decision.","zh":"正确：患者表现出针对该决定的能力，应由患者本人作出决定。"},{"en":"Relatives do not automatically replace a capable adult’s decision-making authority.","zh":"家属不会自动取代有能力成年人的决策权。"},{"en":"The clinician explains and obtains consent but does not consent on the patient’s behalf.","zh":"临床人员负责解释并取得同意，但不能代替患者同意。"},{"en":"A substitute decision-maker is used only when the patient lacks capacity for that decision.","zh":"只有当患者对该决定缺乏能力时，才使用替代决策者。"}],"level":"Clinical","pearl":"Capacity is assessed for the specific decision, not assumed from a diagnosis alone."},{"id":45,"concept":"Consent & Minors","stem":"A mature adolescent clearly understands a low-risk preventive procedure and its alternatives. What is the best first step?","choices":["Assess the adolescent’s capacity and follow applicable law and policy","Ignore the adolescent and speak only to the parent","Proceed without any consent","Assume all minors are incapable"],"answer":0,"why":"Consent involving minors depends on capacity and applicable law; age alone does not always determine decision-making ability.","zh":"未成年人的同意取决于其能力及适用法律；年龄本身并不总能决定其决策能力。","rationales":[{"en":"Correct: assess understanding and follow the jurisdiction’s consent requirements.","zh":"正确：评估其理解能力并遵循当地同意规定。"},{"en":"Excluding a capable adolescent may undermine autonomy and communication.","zh":"排除有能力的青少年可能损害其自主权和沟通。"},{"en":"Some form of valid consent is required unless a lawful emergency exception applies.","zh":"除非适用合法紧急例外，否则必须取得有效同意。"},{"en":"Minor status alone does not prove incapacity in every jurisdiction or circumstance.","zh":"未成年人身份本身并不能在所有地区或情境下证明其无能力。"}],"level":"Board-style","pearl":"For minors, assess capacity and apply local consent law rather than relying on age alone."},{"id":46,"concept":"Informed Refusal","stem":"A capable patient refuses periodontal referral despite progressive attachment loss. What documentation is most appropriate?","choices":["Record only that the patient was difficult","Document the recommendation, reasons, material risks of refusal, alternatives, patient questions, and decision","Delete the diagnosis from the chart","Ask the patient to sign a blank waiver"],"answer":1,"why":"Informed refusal requires a clear record of the recommendation, discussion, risks, alternatives, and the patient’s decision.","zh":"知情拒绝需要清楚记录建议、讨论内容、拒绝风险、替代方案及患者决定。","rationales":[{"en":"Judgmental labels are not objective and do not show informed discussion.","zh":"带评价性的标签不客观，也不能证明进行了知情讨论。"},{"en":"Correct: this creates a complete, defensible record of informed refusal.","zh":"正确：这样可形成完整且可辩护的知情拒绝记录。"},{"en":"Removing the diagnosis falsifies the clinical record.","zh":"删除诊断会使临床记录失真。"},{"en":"A blank waiver does not demonstrate meaningful understanding or discussion.","zh":"空白免责书不能证明患者真正理解或经过讨论。"}],"level":"Clinical","pearl":"Document the substance of informed refusal, not merely the patient’s signature."},{"id":47,"concept":"Mandatory Reporting","stem":"A child presents with injuries and behaviour that create reasonable suspicion of abuse. What should the clinician do?","choices":["Investigate until abuse is proven","Report promptly according to law and document objective observations","Confront the suspected person in the waiting room","Wait for the child to request help"],"answer":1,"why":"Mandatory reporting is generally based on reasonable suspicion; clinicians report concerns rather than conduct their own investigation.","zh":"强制报告通常以合理怀疑为标准；临床人员应报告疑虑，而不是自行调查。","rationales":[{"en":"Clinicians are not required to prove abuse before reporting and should not delay protection.","zh":"临床人员无需在报告前证明虐待，且不应延误保护。"},{"en":"Correct: report as required and chart factual findings and statements.","zh":"正确：依法报告并记录客观发现和陈述。"},{"en":"Public confrontation can increase risk and compromise safety or investigation.","zh":"公开对质可能增加风险并影响安全或调查。"},{"en":"The duty to report does not depend on the child making a formal request.","zh":"报告义务不取决于儿童是否正式求助。"}],"level":"Clinical","pearl":"Report reasonable suspicion promptly and record facts without diagnosing guilt."},{"id":48,"concept":"Privacy Breach","stem":"A clinician accidentally emails a patient’s treatment plan to the wrong recipient. What is the best immediate response?","choices":["Delete the sent message and say nothing","Follow the privacy-breach protocol, notify the appropriate privacy lead, contain the breach, and document actions","Post an apology on social media","Alter the chart to remove evidence"],"answer":1,"why":"Privacy breaches require prompt containment, internal reporting, risk assessment, documentation, and any required notification.","zh":"隐私泄露需要立即控制、内部报告、风险评估、记录，并按要求通知相关方。","rationales":[{"en":"Silence prevents proper containment and may breach legal obligations.","zh":"保持沉默会妨碍适当控制，并可能违反法律义务。"},{"en":"Correct: activate the established breach-response process immediately.","zh":"正确：应立即启动既定的隐私泄露处理流程。"},{"en":"Public posting can disclose more information and worsen the breach.","zh":"公开发帖可能披露更多信息并加重泄露。"},{"en":"Altering records is unethical and destroys the audit trail.","zh":"篡改记录不道德，并会破坏审计轨迹。"}],"level":"Clinical","pearl":"Contain, report, assess, document, and notify as required after a privacy breach."},{"id":49,"concept":"Electronic Communication","stem":"A patient sends a clinical question through the hygienist’s personal social-media account. What is the best response?","choices":["Discuss the full case in direct messages","Move the conversation to an approved secure channel and document clinically relevant communication","Share the message with friends for advice","Ignore all patient communication permanently"],"answer":1,"why":"Clinical communication should occur through secure, approved systems and relevant content should be documented.","zh":"临床沟通应通过安全、获批准的系统进行，并记录与照护相关的内容。","rationales":[{"en":"Personal social media may not meet privacy, security, or recordkeeping requirements.","zh":"个人社交媒体可能不符合隐私、安全或记录要求。"},{"en":"Correct: redirect to a secure channel and preserve relevant information in the record.","zh":"正确：转至安全渠道，并将相关信息纳入病历。"},{"en":"Sharing patient information with friends is an unauthorized disclosure.","zh":"与朋友分享患者信息属于未经授权的披露。"},{"en":"A professional response and redirection are preferable to blanket nonresponse.","zh":"专业回复并转至适当渠道优于完全不回应。"}],"level":"Board-style","pearl":"Keep clinical communication within approved secure channels and document it."},{"id":50,"concept":"Social Media","stem":"A clinician wants to post a dramatic before-and-after oral photograph online. The patient’s name is omitted. What is required before posting?","choices":["Nothing, because the name is absent","Specific informed authorization and confirmation that the image cannot reasonably identify the patient, consistent with policy and law","Only verbal permission from a coworker","A disclaimer that the post is educational"],"answer":1,"why":"Images may identify patients even without names; specific authorization and compliance with privacy rules are required.","zh":"即使没有姓名，影像仍可能识别患者；必须取得特定授权并遵守隐私规定。","rationales":[{"en":"Unique clinical features can make a patient identifiable without a name.","zh":"独特的临床特征即使没有姓名也可能识别患者。"},{"en":"Correct: obtain specific authorization and follow privacy and professional standards.","zh":"正确：取得特定授权并遵守隐私及专业标准。"},{"en":"A coworker cannot authorize disclosure of a patient’s information.","zh":"同事无权授权披露患者信息。"},{"en":"An educational disclaimer does not replace valid patient authorization.","zh":"教育用途声明不能替代有效的患者授权。"}],"level":"Clinical","pearl":"De-identification is not guaranteed merely by removing a name from a clinical image."},{"id":51,"concept":"Record Transfer","stem":"A patient changes offices and asks that records be sent to the new provider. What is the best approach?","choices":["Destroy the originals after sending","Obtain valid authorization, send relevant copies securely, and retain the original according to law","Refuse all transfer requests","Send the entire record through an unsecured personal email"],"answer":1,"why":"Record transfer requires authorization, secure transmission, appropriate disclosure, and retention of the original record.","zh":"病历转移需要有效授权、安全传输、适当披露，并按规定保留原始病历。","rationales":[{"en":"Original records must be retained for the required period.","zh":"原始病历必须按规定期限保留。"},{"en":"Correct: this protects continuity, privacy, and record integrity.","zh":"正确：这样可保障连续照护、隐私和病历完整性。"},{"en":"Patients generally have rights to access and authorize transfer of their information.","zh":"患者通常有权查阅并授权转移其信息。"},{"en":"Unsecured personal email may expose confidential information.","zh":"不安全的个人电子邮件可能泄露机密信息。"}],"level":"Board-style","pearl":"Transfer copies securely with authorization while retaining the original record."},{"id":52,"concept":"Record Retention","stem":"A clinic is closing permanently. What is the most ethical and legally sound plan for patient records?","choices":["Discard them immediately","Arrange secure retention for the required period and inform patients how to access or transfer their records","Give all records to the building landlord","Take selected charts home without safeguards"],"answer":1,"why":"Closing a practice does not end duties of confidentiality, retention, and patient access.","zh":"诊所关闭并不会终止保密、保存及患者查阅病历的义务。","rationales":[{"en":"Immediate destruction may violate retention requirements and harm continuity of care.","zh":"立即销毁可能违反保存规定并影响连续照护。"},{"en":"Correct: secure custody and clear access arrangements must continue.","zh":"正确：必须继续确保安全保管并明确查阅安排。"},{"en":"A landlord is not automatically authorized to possess confidential records.","zh":"房东并不自动有权持有机密病历。"},{"en":"Taking charts home without approved safeguards creates privacy and security risks.","zh":"未经批准将病历带回家会造成隐私和安全风险。"}],"level":"Clinical","pearl":"Record duties survive practice closure."},{"id":53,"concept":"Abandonment","stem":"A patient repeatedly misses appointments. The office decides to end care. Which action best avoids abandonment?","choices":["Stop responding immediately","Provide reasonable written notice, address urgent needs during the transition, offer referral resources, and document the process","Delete the patient from the software","Withhold copies of the record until every disagreement is resolved"],"answer":1,"why":"Proper termination requires notice, continuity planning, emergency coverage as appropriate, and documentation.","zh":"妥善终止照护需要合理通知、连续照护安排、必要的紧急支持和完整记录。","rationales":[{"en":"Abrupt silence can leave the patient without reasonable opportunity to obtain care.","zh":"突然停止回应可能使患者无法合理获得后续照护。"},{"en":"Correct: these steps support continuity and reduce abandonment risk.","zh":"正确：这些步骤有助于连续照护并降低遗弃风险。"},{"en":"Deleting data does not satisfy professional duties and may violate record rules.","zh":"删除数据不能履行专业义务，并可能违反病历规定。"},{"en":"Access to records should not be used improperly as leverage in a dispute.","zh":"不应将病历查阅权不当用作争议中的筹码。"}],"level":"Clinical","pearl":"Termination must be orderly, documented, and designed to preserve continuity."},{"id":54,"concept":"Impaired Colleague","stem":"A dental hygienist appears intoxicated and is about to treat a patient. What is the best immediate action?","choices":["Allow treatment to avoid embarrassment","Prevent unsafe patient care, follow workplace and regulatory reporting procedures, and document objective observations","Post the concern in a staff group chat","Wait until an injury occurs"],"answer":1,"why":"Patient safety takes priority; suspected impairment should be managed promptly through established professional channels.","zh":"患者安全优先；疑似执业受损应立即通过既定专业渠道处理。","rationales":[{"en":"Avoiding embarrassment does not justify exposing a patient to preventable harm.","zh":"避免尴尬不能成为让患者承受可预防伤害的理由。"},{"en":"Correct: stop unsafe practice and follow formal reporting and support procedures.","zh":"正确：阻止不安全执业，并遵循正式报告和支持程序。"},{"en":"Informal group-chat discussion risks gossip and privacy violations.","zh":"在群聊中非正式讨论可能导致流言和隐私问题。"},{"en":"Waiting for harm violates the duty to protect patients.","zh":"等待伤害发生违反保护患者的义务。"}],"level":"Clinical","pearl":"Act on objective safety concerns before patient harm occurs."},{"id":55,"concept":"Competence","stem":"A clinician notices a colleague repeatedly using an unsafe technique despite coaching. What is the best next step?","choices":["Ignore it because colleagues are never accountable for one another","Use the appropriate supervisory or regulatory pathway to protect patients, while documenting objective concerns","Publicly shame the colleague","Change the patient records to hide the errors"],"answer":1,"why":"Persistent unsafe practice requires proportionate escalation through established channels.","zh":"持续的不安全执业需要通过既定渠道按比例升级处理。","rationales":[{"en":"Professionals have duties related to patient safety and may need to report serious concerns.","zh":"专业人员对患者安全负有责任，严重问题可能需要报告。"},{"en":"Correct: escalate objectively through proper channels after reasonable internal steps.","zh":"正确：在合理内部措施后，应通过适当渠道客观升级处理。"},{"en":"Public humiliation is unprofessional and does not create a fair process.","zh":"公开羞辱不专业，也无法形成公正程序。"},{"en":"Altering records is unethical and may create additional legal liability.","zh":"篡改记录不道德，并可能产生额外法律责任。"}],"level":"Board-style","pearl":"Escalate unresolved competence concerns through formal, patient-safety-focused channels."},{"id":56,"concept":"Scope & Delegation","stem":"A dentist asks a dental hygienist to perform a procedure outside the hygienist’s legal scope. What should the hygienist do?","choices":["Perform it because the dentist requested it","Decline, explain the scope limitation, and seek an appropriate alternative","Delegate it to an unregulated assistant","Proceed if the patient signs consent"],"answer":1,"why":"An employer’s request or patient consent cannot expand a regulated professional’s legal scope.","zh":"雇主要求或患者同意都不能扩大受监管专业人员的法定执业范围。","rationales":[{"en":"A supervisor cannot authorize conduct prohibited by law or regulation.","zh":"主管不能授权法律或法规禁止的行为。"},{"en":"Correct: remain within scope and arrange a lawful alternative.","zh":"正确：应在执业范围内行事并安排合法替代方案。"},{"en":"An unauthorized task cannot be made lawful by passing it to another person.","zh":"未经授权的任务不能通过转交他人而变得合法。"},{"en":"Consent does not legalize practice outside professional scope.","zh":"患者同意不能使超范围执业合法化。"}],"level":"Clinical","pearl":"Delegation and consent never override statutory scope."},{"id":57,"concept":"Conflict of Interest","stem":"A clinician owns shares in a product company and recommends that company’s device to patients. What is the best ethical response?","choices":["Hide the financial interest","Disclose the relevant interest, base the recommendation on evidence and patient need, and offer reasonable alternatives","Recommend the device to every patient","Avoid documenting the recommendation"],"answer":1,"why":"Conflicts should be disclosed and managed so patient welfare, evidence, and choice remain central.","zh":"应披露并管理利益冲突，确保患者利益、证据和选择权处于核心位置。","rationales":[{"en":"Concealment undermines trust and informed decision-making.","zh":"隐瞒会损害信任和知情决策。"},{"en":"Correct: transparency and evidence-based alternatives reduce bias.","zh":"正确：透明披露和循证替代方案可减少偏差。"},{"en":"Universal recommendation ignores individual indications and autonomy.","zh":"对所有患者一律推荐忽视个体适应证和自主权。"},{"en":"Relevant recommendations and consent discussions should be documented.","zh":"相关建议和同意讨论应记录在案。"}],"level":"Clinical","pearl":"Manage conflicts through disclosure, evidence, alternatives, and patient-first judgment."},{"id":58,"concept":"Ethical Principles","stem":"A patient wants an unnecessary procedure that offers no expected benefit and carries avoidable risk. Which response best balances autonomy and nonmaleficence?","choices":["Provide it because autonomy is absolute","Explain why it is not clinically indicated, decline unsafe care, and discuss appropriate alternatives","Dismiss the patient without discussion","Misrepresent the risks so the patient changes their mind"],"answer":1,"why":"Respect for autonomy does not require a clinician to provide nonbeneficial or harmful treatment.","zh":"尊重自主权并不要求临床人员提供无益或有害的治疗。","rationales":[{"en":"Autonomy allows informed choices among clinically acceptable options, not a right to unsafe treatment.","zh":"自主权允许患者在临床可接受方案中知情选择，并不意味着有权要求不安全治疗。"},{"en":"Correct: honest explanation, professional refusal, and alternatives balance key duties.","zh":"正确：诚实解释、专业拒绝和提供替代方案可平衡各项义务。"},{"en":"Immediate dismissal is unnecessary and may undermine continuity and communication.","zh":"立即终止关系并非必要，且可能损害连续照护和沟通。"},{"en":"Deception violates veracity and invalidates informed decision-making.","zh":"欺骗违反诚实原则，并会使知情决策失效。"}],"level":"Clinical","pearl":"Patient autonomy operates within the boundaries of safe, professionally acceptable care."},{"id":59,"concept":"Adverse Events","stem":"During treatment, an instrument fractures and a fragment is retained. What is the most appropriate response?","choices":["Say nothing unless symptoms occur","Stop, assess and manage the patient, disclose the event honestly, arrange necessary referral, and document facts and follow-up","Remove all reference to the event from the chart","Blame the patient in the record"],"answer":1,"why":"Adverse events require immediate care, transparent disclosure, appropriate follow-up, and objective documentation.","zh":"不良事件需要立即处理、透明披露、适当随访和客观记录。","rationales":[{"en":"Nondisclosure may delay care and violates ethical duties of honesty and accountability.","zh":"不披露可能延误治疗，并违反诚实和责任义务。"},{"en":"Correct: prioritize safety, communicate openly, refer as needed, and document.","zh":"正确：应优先保障安全、坦诚沟通、必要时转诊并记录。"},{"en":"Deleting evidence compromises the record and may constitute misconduct.","zh":"删除证据会损害病历完整性，并可能构成不当行为。"},{"en":"Unsupported blame is judgmental and does not accurately document the event.","zh":"无依据责怪患者带有评价性，不能准确记录事件。"}],"level":"Clinical","pearl":"Manage adverse events with care, candour, follow-up, and factual documentation."},{"id":60,"concept":"Negligence & Misconduct","stem":"Which situation most clearly represents professional misconduct rather than an unintended clinical error?","choices":["A recognized complication occurs despite competent care and informed consent","A clinician knowingly falsifies records to conceal unauthorized treatment","A patient experiences expected postoperative sensitivity","A clinician refers a case beyond their competence"],"answer":1,"why":"Intentional dishonesty and concealment are professional misconduct, distinct from a complication or appropriately managed error.","zh":"故意造假和隐瞒属于专业不当行为，与并发症或妥善处理的错误不同。","rationales":[{"en":"A complication can occur without negligence or misconduct when care meets standards.","zh":"在符合标准的照护中也可能发生并发症，并不必然构成疏忽或不当行为。"},{"en":"Correct: knowingly falsifying records is deliberate professional misconduct.","zh":"正确：故意伪造病历属于蓄意的专业不当行为。"},{"en":"An expected side effect is not itself evidence of misconduct.","zh":"预期副作用本身并不能证明专业不当。"},{"en":"Appropriate referral demonstrates recognition of limits and supports patient safety.","zh":"适当转诊体现对能力边界的认识，并有助于患者安全。"}],"level":"Board-style","pearl":"Intentional deception is misconduct; a poor outcome alone does not prove negligence."}];
window.FULL_BANK=LAW_BANK;
